-- Record the actual D-ID Talks prompt capabilities and expose facial-expression guidance only.
update model_deployment
set config_json = config_json || $capabilities$
{
  "performancePromptMode":"facial-expression-keywords",
  "supportedExpressions":["neutral","happy","serious","surprise"],
  "supportsBodyMotionPrompt":false,
  "supportsCameraPrompt":false,
  "supportsNegativePrompt":false,
  "maxImageDimension":1280
}
$capabilities$::jsonb,
    updated_at = now()
where code = 'did-talks-v1-video';

insert into feature_version (
    id, feature_id, version, input_schema_json, ui_schema_json,
    output_schema_json, config_json, created_at
)
select
    '42000000-0000-0000-0000-000000000713',
    definition.id,
    13,
    $input$
